const oldestBuyerRunsSince = `-- name: OldestBuyerRunsSince :many
SELECT created_at FROM procurement.agent_runs
WHERE buyer_id = $1 AND created_at > $2::timestamptz
ORDER BY created_at DESC
LIMIT $3::int
`

type OldestBuyerRunsSinceParams struct {
	BuyerID int64
	Since   time.Time
	MaxRows int32
}

// 買家在 @since 之後建立的 run 的時間，新的在前，最多 @max_rows 筆；每分鐘送出上限用它判斷並算出要等多久。
func (q *Queries) OldestBuyerRunsSince(ctx context.Context, arg OldestBuyerRunsSinceParams) ([]time.Time, error) {
	rows, err := q.db.Query(ctx, oldestBuyerRunsSince, arg.BuyerID, arg.Since, arg.MaxRows)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []time.Time{}
	for rows.Next() {
		var created_at time.Time
		if err := rows.Scan(&created_at); err != nil {
			return nil, err
		}
		items = append(items, created_at)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const resolveInterrupt = `-- name: ResolveInterrupt :execrows
UPDATE procurement.agent_run_interrupts
SET status = 'RESOLVED', closed_at = $1
WHERE id = $2 AND status = 'PENDING'
`

type ResolveInterruptParams struct {
	Now *time.Time
	ID  uuid.UUID
}

// 回答成功的提交點：只有仍是 PENDING 的中斷會轉。
func (q *Queries) ResolveInterrupt(ctx context.Context, arg ResolveInterruptParams) (int64, error) {
	result, err := q.db.Exec(ctx, resolveInterrupt, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setRunJob = `-- name: SetRunJob :exec
UPDATE procurement.agent_runs SET job_id = $1 WHERE id = $2
`

type SetRunJobParams struct {
	JobID *int64
	ID    uuid.UUID
}

func (q *Queries) SetRunJob(ctx context.Context, arg SetRunJobParams) error {
	_, err := q.db.Exec(ctx, setRunJob, arg.JobID, arg.ID)
	return err
}

const transitionRun = `-- name: TransitionRun :one
UPDATE procurement.agent_runs
SET status = $1,
    failure_reason = $2,
    started_at = CASE WHEN $1::text = 'RUNNING' THEN $3::timestamptz ELSE started_at END,
    completed_at = CASE WHEN $4::boolean THEN $3::timestamptz ELSE completed_at END,
    updated_at = $3::timestamptz
WHERE id = $5 AND status = ANY($6::text[])
RETURNING id, buyer_id, request_id, conversation_id, interrupt_id, candidate_set_id, publication_id, run_type, status, failure_reason, result_revision_id, last_event_seq, min_available_seq, client_request_id, job_id, quota_period_start, created_at, started_at, completed_at, updated_at
`

type TransitionRunParams struct {
	ToStatus      string
	FailureReason *string
	Now           time.Time
	Terminal      bool
	ID            uuid.UUID
	FromStatuses  []string
}

// 唯一的狀態轉換：只有目前狀態在 @from_statuses（由允許的邊算出）時才寫，UPDATE 持有 run 列鎖到 transaction 結束。
func (q *Queries) TransitionRun(ctx context.Context, arg TransitionRunParams) (ProcurementAgentRun, error) {
	row := q.db.QueryRow(ctx, transitionRun,
		arg.ToStatus,
		arg.FailureReason,
		arg.Now,
		arg.Terminal,
		arg.ID,
		arg.FromStatuses,
	)
	var i ProcurementAgentRun
	err := row.Scan(
		&i.ID,
		&i.BuyerID,
		&i.RequestID,
		&i.ConversationID,
		&i.InterruptID,
		&i.CandidateSetID,
		&i.PublicationID,
		&i.RunType,
		&i.Status,
		&i.FailureReason,
		&i.ResultRevisionID,
		&i.LastEventSeq,
		&i.MinAvailableSeq,
		&i.ClientRequestID,
		&i.JobID,
		&i.QuotaPeriodStart,
		&i.CreatedAt,
		&i.StartedAt,
		&i.CompletedAt,
		&i.UpdatedAt,
	)
	return i, err
}
